import{_ as s,C as r,o as c,c as i,j as t,a as o,E as a,a5 as n}from"./chunks/framework.DtspaGiy.js";const w=JSON.parse('{"title":"Writing in Blank","description":"","frontmatter":{},"headers":[],"relativePath":"guide/writing.md","filePath":"guide/writing.md"}'),h={name:"guide/writing.md"};function l(u,e,p,m,g,b){const d=r("Shot");return c(),i("div",null,[e[0]||(e[0]=t("h1",{id:"writing-in-blank",tabindex:"-1"},[o("Writing in Blank "),t("a",{class:"header-anchor",href:"#writing-in-blank","aria-label":'Permalink to "Writing in Blank"'},"​")],-1)),e[1]||(e[1]=t("p",null,[o("Blank shows your text as it will look, not as markdown syntax, and on the lines and pages it will have on paper (see "),t("a",{href:"./pages#on-the-screen"},"Pages"),o("). You format with "),t("a",{href:"./shortcuts"},"keyboard shortcuts"),o(", by typing markdown, which Blank turns into formatting as you go, or with the toolbar at the top when you'd rather point and click.")],-1)),a(d,{src:"writing.gif",alt:"Typing # and a title makes a heading; quotes curl and two hyphens become a dash; **slow** turns bold and *quiet* italic; a hyphen starts a list and > a quote, while the toolbar shows the style at the cursor"}),e[2]||(e[2]=t("h2",{id:"toolbar",tabindex:"-1"},[o("The toolbar "),t("a",{class:"header-anchor",href:"#toolbar","aria-label":'Permalink to "The toolbar {#toolbar}"'},"​")],-1)),e[3]||(e[3]=t("p",null,[o("The second row at the top of the window has everything to format your text, and shows how the text at the cursor is set: Bold lights up in bold text, the list you're in is pressed, and the style menu says "),t("em",null,"Heading 2"),o(" while you're in one.")],-1)),a(d,{src:"toolbar.png",alt:"The toolbar above a centered heading: the style menu says Text for the line below it, and the button for centered text is pressed"}),e[4]||(e[4]=n('<p>From left to right: undo and redo; the style menu (text, headings 1–6, quote and code block, each shown in its own style); bold, italic, underline, code and link; bulleted and numbered lists, quote, outdent and indent; the four alignments; and <strong>Insert</strong> for an image, a table, a horizontal line or a page break. Clicking a button leaves your cursor and selection where they were, so you can go on typing. Hover over a button to see its shortcut.</p><p>In a narrow window, what doesn&#39;t fit moves into the <strong>More</strong> button (⋯) at the end of the row: first Insert, then alignment, then indent and quote, then the lists.</p><p>Prefer the keyboard? <code>Alt</code> <code>F10</code> takes you into the toolbar, and <code>F6</code> gets there too, after the tabs. The arrow keys move from button to button, <code>Home</code> and <code>End</code> jump to the ends, Enter or Space presses a button, <code>↓</code> opens a menu, and <code>Escape</code> takes you back to your text, right where you were.</p><h2 id="marks" tabindex="-1">Bold, italic and underline <a class="header-anchor" href="#marks" aria-label="Permalink to &quot;Bold, italic and underline {#marks}&quot;">​</a></h2><p><code>Mod</code> <code>B</code>, <code>Mod</code> <code>I</code> and <code>Mod</code> <code>U</code> make the selected text bold, italic or underlined, and <code>Mod</code> <code>E</code> code. If only part of the selection has it, the whole selection gets it; press again to take it away. Lists and quotes work the same way: <code>Mod</code> <code>8</code>, <code>Mod</code> <code>9</code> and <code>Mod</code> <code>G</code> turn a list or quote on, and off again when you&#39;re in one. In a numbered list, <code>Mod</code> <code>8</code> turns it into a bulleted one, and back with <code>Mod</code> <code>9</code>.</p><h2 id="alignment" tabindex="-1">Alignment <a class="header-anchor" href="#alignment" aria-label="Permalink to &quot;Alignment {#alignment}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Alignment</th><th>Shortcut</th></tr></thead><tbody><tr><td>Align left</td><td><code>Mod</code> <code>Shift</code> <code>L</code></td></tr><tr><td>Center</td><td><code>Mod</code> <code>Shift</code> <code>E</code></td></tr><tr><td>Align right</td><td><code>Mod</code> <code>Shift</code> <code>R</code></td></tr><tr><td>Justify</td><td><code>Mod</code> <code>Shift</code> <code>J</code></td></tr></tbody></table><p>These align the paragraphs and headings you&#39;ve selected, or the one the cursor is in; press the same shortcut again to go back to the left. Justified text runs straight down both edges, by widening the spaces between words; the last line of a paragraph stays as it is. A new paragraph you start with Enter keeps the alignment, as in Word.</p><p>In a table, Align left, Center and Align right align the selected columns. Lists, quotes and form fields always stay on the left. The pages, the PDF and Word documents show your alignment just as you set it. See <a href="./files#markdown">Files &amp; formats</a> for how it&#39;s kept in the file.</p><h2 id="format-as-you-type" tabindex="-1">Format as you type <a class="header-anchor" href="#format-as-you-type" aria-label="Permalink to &quot;Format as you type&quot;">​</a></h2><p>At the start of an empty line, type one of these to turn the line into a block:</p><table tabindex="0"><thead><tr><th>Type at the start of a line</th><th>Then</th><th>You get</th></tr></thead><tbody><tr><td><code>#</code> … <code>######</code></td><td>Space</td><td>Heading 1–6</td></tr><tr><td><code>-</code> <code>*</code> <code>+</code></td><td>Space</td><td>Bullet list</td></tr><tr><td><code>1.</code> (any number)</td><td>Space</td><td>Numbered list</td></tr><tr><td><code>&gt;</code></td><td>Space</td><td>Blockquote</td></tr><tr><td><code>---</code> <code>***</code> <code>___</code></td><td>Enter</td><td>Horizontal line</td></tr><tr><td><code>+++</code></td><td>Enter</td><td><a href="./pages#page-breaks">Page break</a></td></tr><tr><td><code>[toc]</code></td><td>Enter</td><td><a href="./blocks#toc">Table of contents</a></td></tr><tr><td><code>```</code> or <code>```lang</code></td><td>Enter</td><td>Code block</td></tr><tr><td><code>| Name | Qty |</code></td><td>Enter</td><td>Table</td></tr></tbody></table><p>Changed your mind? <code>Mod</code> <code>Z</code> right away gives you back the line as you typed it.</p><p>Inline markdown works too: <code>**bold**</code>, <code>*italic*</code>, <code>`code`</code>, <code>[title](url)</code> and plain URLs become formatting once you finish the word. See <a href="./autocorrect">Autocorrect</a> for everything Blank corrects.</p><p>Code is set in IBM Plex Mono. <code>Mod</code> + Click on a link opens it in your browser. Emoji appear in black and white, in the colour of your text. Chinese, Japanese, Korean and other scripts use the fonts your computer has for them. Whatever you write, it looks on paper just as it does on the screen, and a word too long for its line, like a long web address, simply carries on to the next one.</p><h2 id="code" tabindex="-1">Code blocks <a class="header-anchor" href="#code" aria-label="Permalink to &quot;Code blocks {#code}&quot;">​</a></h2><p>Type <code>```</code> and Enter at the start of a line to start a code block. In it, <code>Tab</code> and <code>Shift</code> <code>Tab</code> work as in a code editor: select some lines and <code>Tab</code> indents all of them by 4 spaces, <code>Shift</code> <code>Tab</code> outdents them, and the same lines stay selected, so you can press again to go further. Each line moves to the next or the previous step of 4, so a line indented by 6 spaces outdents to 4, not 2, and lines without indentation stay where they are. Without a selection, <code>Tab</code> puts in spaces up to the next step, and <code>Shift</code> <code>Tab</code> outdents the line the cursor is on. Code indented with tabs keeps its tabs. Each press is one step for <code>Mod</code> <code>Z</code>. Prefer 2 spaces? Set it in <a href="./configuration#code-blocks">blank.json</a>.</p><h2 id="blocks" tabindex="-1">Blocks <a class="header-anchor" href="#blocks" aria-label="Permalink to &quot;Blocks&quot;">​</a></h2><p>The <strong>Blocks</strong> pane (<code>Mod</code> <code>Alt</code> <code>B</code>) puts a table of contents, a form such as a recipe, or a drawing into your document: click a tile, or drag it between two paragraphs. See <a href="./blocks">Blocks</a>.</p><h2 id="tables" tabindex="-1">Tables <a class="header-anchor" href="#tables" aria-label="Permalink to &quot;Tables&quot;">​</a></h2><p>Press <code>Mod</code> <code>T</code>, pick a size with the arrow keys and press Enter. <code>Tab</code> takes you from cell to cell and adds a row at the end. <a href="./tables">Tables</a> has everything about making, filling and saving them.</p><h2 id="images" tabindex="-1">Images <a class="header-anchor" href="#images" aria-label="Permalink to &quot;Images&quot;">​</a></h2><p>Press <code>Mod</code> <code>Alt</code> <code>I</code> to add an image where the cursor is. In the dialog, press <em>Choose file…</em> (Tab gets you there) to pick a picture from your computer, give it a short description and press Enter. Blank puts the picture into the document itself, so your markdown file stays a single file you can move, copy and send without losing images. Large pictures are scaled down to a size that still prints well.</p><p>Instead of choosing a file, you can also type an address into the dialog, or type <code>![description](address)</code> and a space right in the text:</p><ul><li>a web address, like <code>https://example.com/map.png</code>,</li><li>a file next to your document, like <code>images/chart.png</code>, which appears once the document has been saved, since Blank needs to know its folder,</li><li>any file on your computer, like <code>/home/me/logo.png</code>.</li></ul><p>These images stay where they are and the document links to them.</p><p>To change or remove an image, put the cursor right before or after it and press <code>Mod</code> <code>Alt</code> <code>I</code> again.</p><p>Images are as wide as they are in the file, up to the width of the page, and <a href="./files#pdf">PDFs and Word documents</a> include them at that size.</p><h2 id="tabs" tabindex="-1">Tabs <a class="header-anchor" href="#tabs" aria-label="Permalink to &quot;Tabs&quot;">​</a></h2><p>Keep several documents open at once, each in a tab at the top of the window. <code>Mod</code> <code>N</code> or <strong>+</strong> starts a new one, and a double-click on the empty part of the row does too. Every file you open gets a tab of its own, next to the one you&#39;re in; open a file that&#39;s already open and Blank just takes you to its tab.</p><ul><li><strong>Switch</strong> with <code>Ctrl</code> <code>Tab</code> and <code>Ctrl</code> <code>Shift</code> <code>Tab</code>, or <code>Ctrl</code> <code>Page Down</code> and <code>Ctrl</code> <code>Page Up</code>, or click a tab. Each tab keeps its own place in the text and its own undo.</li><li><strong>Close</strong> with <code>Mod</code> <code>W</code>, the × on a tab or a middle click. Changes you haven&#39;t saved show as a dot instead of the ×, and Blank asks whether to save them before the tab closes. <code>Mod</code> <code>Shift</code> <code>T</code> opens the file you closed last again.</li><li><strong>Reorder</strong> by dragging a tab, or with <code>Ctrl</code> <code>Shift</code> <code>Page Up</code> and <code>Page Down</code>.</li><li><strong>Right-click</strong> a tab to close the others or those to its right, to save it, or to copy its file&#39;s path.</li><li><strong>Get there from the keyboard</strong> with <code>F6</code>, which takes you from the text to the tabs, then to the toolbar, and back. The arrow keys move between tabs, <code>Enter</code> shows one, <code>Delete</code> closes it and <code>Esc</code> takes you back to the text.</li></ul><p>The window is named after the tab you&#39;re in, and pointing at a tab shows where its file is.</p><h2 id="blank-remembers-your-documents" tabindex="-1">Blank remembers your documents <a class="header-anchor" href="#blank-remembers-your-documents" aria-label="Permalink to &quot;Blank remembers your documents&quot;">​</a></h2><p>Blank keeps what you write as you go, at least once a second and once more when you close the window, and restores every tab on the next start, unsaved changes included, together with the theme and the language. So you can close the window mid-thought without saving, and pick up right where you left off. Closing the window never asks about saving; only closing a tab does.</p><p>A tab whose file you saved shows the file as it is on disk now, in case it changed meanwhile.</p><h2 id="save-open-and-export" tabindex="-1">Save, open and export <a class="header-anchor" href="#save-open-and-export" aria-label="Permalink to &quot;Save, open and export&quot;">​</a></h2><p>Your documents are plain markdown files: <code>Mod</code> <code>S</code> saves the tab you&#39;re in, <code>Mod</code> <code>O</code> opens one or several files, also Word documents. To share a piece, export it as a PDF with <code>Mod</code> <code>Alt</code> <code>P</code> or as a Word document with <code>Mod</code> <code>Alt</code> <code>W</code>. <a href="./files">Files &amp; formats</a> has everything about PDF and Word.</p><h2 id="the-status-bar" tabindex="-1">The status bar <a class="header-anchor" href="#the-status-bar" aria-label="Permalink to &quot;The status bar&quot;">​</a></h2><p>The top of the window shows the open file, <em>Untitled</em>, or the <a href="./files#open-word-documents">Word document</a> an untitled document was imported from.</p><p>The bar at the bottom shows where you are and what&#39;s switched on. Click any item in it; rest the mouse on one to see its name and shortcut.</p>',40)),a(d,{src:"status-bar.gif",alt:"The mouse rests on the word count and a card with the words, characters, pages and reading time opens; then a click on the view button switches from page ends to pages"}),e[5]||(e[5]=n('<table tabindex="0"><thead><tr><th>Item</th><th>What it shows</th><th>Click it to</th><th>Keys</th></tr></thead><tbody><tr><td><em>348 words</em></td><td>how many words the document has</td><td>see the details: characters, pages, reading time and the words you selected. Resting the mouse on it opens them too</td><td><code>Mod</code> <code>Alt</code> <code>C</code></td></tr><tr><td><em>Page 2 of 5</em></td><td>the page you&#39;re looking at</td><td>jump to another page, listed with the first heading on each</td><td></td></tr><tr><td><em>A4</em></td><td>the <a href="./pages#page-setup">paper</a></td><td>open the page setup</td><td><code>Mod</code> <code>Alt</code> <code>U</code></td></tr><tr><td><em>EN</em></td><td>the <a href="./autocorrect#language">language</a></td><td>choose another one</td><td><code>Mod</code> <code>Alt</code> <code>L</code></td></tr><tr><td><em>Spelling</em></td><td>whether <a href="./spelling">spell check</a> is on (<em>Spelling off</em> when it isn&#39;t)</td><td>turn spell check on or off</td><td><code>Mod</code> <code>Alt</code> <code>S</code></td></tr><tr><td>‹ ›</td><td>while spell check is on and the window is wide enough</td><td>go to the previous or next misspelled word</td><td><code>Mod</code> <code>Alt</code> <code>Shift</code> <code>N</code>, <code>Mod</code> <code>Alt</code> <code>N</code></td></tr><tr><td>the view</td><td><a href="./pages#on-the-screen">pages or page ends</a>, whichever you&#39;re in</td><td>switch to the other</td><td><code>Mod</code> <code>Alt</code> <code>V</code></td></tr><tr><td>focus mode</td><td>whether <a href="#focus-mode">focus mode</a> is on</td><td>turn it on or off</td><td><code>Mod</code> <code>Shift</code> <code>F</code></td></tr></tbody></table><p>Next to the word count, the bar tells you for a moment what just happened, like <em>2 rows added</em>, and screen readers read it out. The details of the word count close as soon as you type on; with <code>Mod</code> <code>Alt</code> <code>C</code>, screen readers read them out as well.</p><h2 id="focus-mode" tabindex="-1">Focus mode <a class="header-anchor" href="#focus-mode" aria-label="Permalink to &quot;Focus mode&quot;">​</a></h2><p>When you want only the page, turn on focus mode with <code>Mod</code> <code>Shift</code> <code>F</code> or the last button of the status bar. Nothing changes at first. As soon as you type, the tabs, the toolbar, the panes, the outline and the status bar fade out, slowly, and the page stays exactly where it was. Move the mouse and they&#39;re back at once.</p>',4)),a(d,{src:"focus-mode.gif",alt:"Mod Shift F turns on focus mode; as the typing starts, the tabs, the toolbar and the status bar fade out and only the page stays; a move of the mouse brings them back, and Esc leaves focus mode"}),e[6]||(e[6]=n('<ul><li>The bars also fade once the mouse has rested for 3 seconds. Choose 10 seconds, or only when typing, in the <a href="./settings#appearance">settings</a>.</li><li>They never fade while the mouse is on one of them, or while a menu, a dialog or the header and footer strip is open.</li><li>Every shortcut still works while they&#39;re hidden, and <code>F6</code> brings them back to move through them with the keyboard.</li><li><code>Esc</code> leaves focus mode, unless something else is open that <code>Esc</code> closes first.</li></ul>',1))])}const y=s(h,[["render",l]]);export{w as __pageData,y as default};
